import os
import sys


def normalize(line):
    s = line.strip().lower()
    if s.count("@") != 1:
        return None
    local, domain = s.split("@")
    if not local:
        return None
    if not domain or "." not in domain:
        return None
    if domain.startswith(".") or domain.endswith("."):
        return None
    if domain == "gmail.com":
        plus = local.find("+")
        if plus != -1:
            local = local[:plus]
        local = local.replace(".", "")
    return local + "@" + domain


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "emails.txt")
    with open(path, "r", encoding="utf-8", errors="surrogateescape", newline=None) as f:
        lines = f.read().split("\n")

    valid = set()
    invalid = 0
    for line in lines:
        if not line.strip():
            continue
        n = normalize(line)
        if n is None:
            invalid += 1
        else:
            valid.add(n)

    out = sys.stdout
    for addr in sorted(valid, key=lambda a: a.encode("utf-8", "surrogateescape")):
        out.write(addr + "\n")
    out.write("invalid %d\n" % invalid)


if __name__ == "__main__":
    main()

