    base = os.environ["INPUT"]
    path = os.path.join(base, "numbers.txt")
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        data = f.read()
    out = []
    for line in data.splitlines():
        s = line.strip()
        if not s:
            continue
        out.append(f"{s} = {convert(s)}")
    if out:
        print("\n".join(out))


