def check(line):
    pairs = {')': '(', ']': '[', '}': '{'}
    closer = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in closer:
            stack.append(ch)
        elif ch in pairs:
