import os
import re

INT_RE = re.compile(r"^[+-]?[0-9]+$")


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "timings.log")
    groups = {}
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 3:
            continue
        method, p, ms = parts
        if not INT_RE.match(ms):
            continue
        groups.setdefault((method, p), []).append(int(ms))

    def key(k):
        enc = lambda s: s.encode("utf-8", errors="surrogateescape")
        return (enc(k[0]), enc(k[1]))

    def pct(t, P):
        n = len(t)
        r = (P * n + 99) // 100
        if r < 1:
            r = 1
        return t[r - 1]

    out = []
    for k in sorted(groups, key=key):
        t = sorted(groups[k])
        out.append(
            "%s %s count=%d p50=%d p95=%d max=%d"
            % (k[0], k[1], len(t), pct(t, 50), pct(t, 95), t[-1])
        )
    if out:
        print("\n".join(out))


if __name__ == "__main__":
    main()

import os
import heapq


def dijkstra(adj, src):
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float("inf")):
            continue
        for v, w in adj.get(u, {}).items():
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")
    with open(path, "r", encoding="utf-8") as f:
        lines = f.read().splitlines()

    adj = {}
    trips = []
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0] == "road" and len(parts) == 4:
            a, b = parts[1], parts[2]
            try:
                c = int(parts[3])
            except ValueError:
                continue
            for x, y in ((a, b), (b, a)):
                m = adj.setdefault(x, {})
                if y not in m or c < m[y]:
                    m[y] = c
        elif parts[0] == "trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))

    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = dijkstra(adj, y)
        dist = cache[y]
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        route = [x]
        cur = x
        while cur != y:
            best = None
            for v, w in adj.get(cur, {}).items():
                if v in dist and dist[cur] == w + dist[v]:
                    if best is None or v.encode("utf-8") < best.encode("utf-8"):
                        best = v
            cur = best
            route.append(cur)
        out.append(" -> ".join(route) + f" {dist[x]}")

    print("\n".join(out))


