    main()

import os
import sys
import heapq


def parse(data):
    adj = {}
    trips = []
    for raw in data.splitlines():
        line = raw.strip()
        if not line or line.startswith(b"#"):
            continue
        parts = line.split()
        if parts[0] == b"road" and len(parts) == 4:
            try:
                cost = int(parts[3])
            except ValueError:
                continue
            a, b = parts[1], parts[2]
            adj.setdefault(a, []).append((b, cost))
            adj.setdefault(b, []).append((a, cost))
        elif parts[0] == b"trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))
    return adj, trips


def cheapest(adj, src, dst):
    if src == dst:
        return 0, [src]
    best = {src: (0, [src])}
    heap = [(0, [src])]
    done = set()
    while heap:
        cost, path = heapq.heappop(heap)
        node = path[-1]
        if node in done:
            continue
        done.add(node)
        if node == dst:
            return cost, path
        for nxt, w in adj.get(node, ()):
            if nxt in done:
                continue
            nc = cost + w
            np = path + [nxt]
            cur = best.get(nxt)
            if cur is None or (nc, np) < cur:
                best[nxt] = (nc, np)
                heapq.heappush(heap, (nc, np))
    return None


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "routes.txt"), "rb") as f:
        data = f.read()
    adj, trips = parse(data)
    out = []
    for src, dst in trips:
        if src == dst:
            out.append(src + b" 0")
            continue
        res = cheapest(adj, src, dst)
        if res is None:
            out.append(src + b" " + dst + b" unreachable")
        else:
            cost, path = res
            out.append(b" -> ".join(path) + b" " + str(cost).encode())
    sys.stdout.buffer.write(b"".join(l + b"\n" for l in out))
    sys.stdout.buffer.flush()


