import os
import sys
import heapq


def dijkstra(adj, src):
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist.get(u):
            continue
        for v, w in adj.get(u, {}).items():
            nd = d + w
            if nd < dist.get(v, nd + 1):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", errors="surrogateescape")

    adj = {}
    trips = []
    for raw in data.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "road" and len(parts) == 4:
            a, b = parts[1], parts[2]
            try:
                c = int(parts[3])
            except ValueError:
                continue
            if c <= 0:
                continue
            for x, y in ((a, b), (b, a)):
                m = adj.setdefault(x, {})
                if y not in m or c < m[y]:
                    m[y] = c
        elif parts[0] == "trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))

    def key(s):
        return s.encode("utf-8", errors="surrogateescape")

    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = dijkstra(adj, y)
        dist = cache[y]
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        route = [x]
        cur = x
        while cur != y:
            dc = dist[cur]
            best = None
            for v, w in adj[cur].items():
                dv = dist.get(v)
                if dv is not None and dv + w == dc:
                    if best is None or key(v) < key(best):
                        best = v
            cur = best
            route.append(cur)
        out.append(" -> ".join(route) + f" {dist[x]}")

    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


