import json
import os
import sys


def merge(base, override):
    result = dict(base) if isinstance(base, dict) else {}
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict):
            result[key] = merge(result.get(key), value)
        else:
            result[key] = value
    return result


def flatten(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
            return
        for key, child in value.items():
            flatten(child, key if path is None else path + "." + key, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
            return
        for index, child in enumerate(value):
            flatten(child, str(index) if path is None else path + "." + str(index), out)
    else:
        out.append((path, json.dumps(value, ensure_ascii=False)))


def main():
    directory = os.environ["INPUT"]
    with open(os.path.join(directory, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(directory, "override.json"), encoding="utf-8") as f:
        override = json.load(f)

    merged = merge(base, override)

    leaves = []
    for key, value in merged.items():
        flatten(value, key, leaves)
    leaves.sort(key=lambda item: item[0].encode("utf-8"))

    lines = [path + "=" + text for path, text in leaves]
    sys.stdout.write("".join(line + "\n" for line in lines))


