import json
import os
import sys


def merge(base, override):
    result = dict(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = value
    return result


def leaves(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
            return
        for k, v in value.items():
            leaves(v, k if path is None else path + "." + k, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
            return
        for i, v in enumerate(value):
            leaves(v, str(i) if path is None else path + "." + str(i), out)
    else:
        out.append((path, json.dumps(value)))


def main():
    root = os.environ["INPUT"]
    with open(os.path.join(root, "base.json"), "r", encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(root, "override.json"), "r", encoding="utf-8") as f:
        override = json.load(f)

    merged = merge(base, override)
    out = []
    for k, v in merged.items():
        leaves(v, k, out)
    out.sort(key=lambda item: item[0].encode("utf-8"))

    lines = [f"{p}={v}" for p, v in out]
    if lines:
        sys.stdout.write("\n".join(lines) + "\n")


