def list_files(path):
    names = []
    for entry in os.scandir(path):
        if entry.is_file(follow_symlinks=False):
            names.append(entry.name)
    return names


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def write_bytes(path, data):
    tmp = path + ".tmp-sync"
    # Avoid clobbering a dst-only file that happens to have the tmp name.
    if os.path.exists(tmp):
        with open(path, "wb") as f:
            f.write(data)
        return
    try:
        with open(tmp, "wb") as f:
            f.write(data)
        os.replace(tmp, path)
    except OSError:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass
        with open(path, "wb") as f:
            f.write(data)


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    src_names = list_files(src)
    dst_names = set(list_files(dst))

    out = []
    for name in sorted(src_names, key=lambda n: os.fsencode(n)):
        data = read_bytes(os.path.join(src, name))
        target = os.path.join(dst, name)
        if name not in dst_names:
            write_bytes(target, data)
            out.append("added " + name)
        else:
            if read_bytes(target) == data:
                out.append("same " + name)
            else:
                write_bytes(target, data)
                out.append("updated " + name)

    kept = len(dst_names - set(src_names))
    out.append("kept %d" % kept)
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

