import json
import os
import sys


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (OSError, ValueError):
        pass
    return {}


def save(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
        f.flush()
        os.fsync(f.fileno())


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]
    users = load(kv_path)
    changed = False
    out = []

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8") as f:
        lines = f.read().splitlines()

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd, args = parts[0], parts[1:]
        if cmd == "put" and len(args) == 3:
            uid, name, email = args
            users[uid] = {"id": uid, "name": name, "email": email}
            changed = True
            out.append("ok " + uid)
        elif cmd == "rename" and len(args) == 2:
            uid, name = args
            if uid in users:
                users[uid]["name"] = name
                changed = True
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "get" and len(args) == 1:
            uid = args[0]
            u = users.get(uid)
            if u is None:
                out.append("missing " + uid)
            else:
                rec = {"id": uid, "name": u.get("name", ""), "email": u.get("email", "")}
                out.append(json.dumps(rec, ensure_ascii=False, separators=(",", ":")))
        elif cmd == "del" and len(args) == 1:
            uid = args[0]
            if uid in users:
                del users[uid]
                changed = True
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "count" and len(args) == 0:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    if changed:
        save(kv_path, users)

    sys.stdout.write("".join(s + "\n" for s in out))


if __name__ == "__main__":
    main()

import json
import os
import sys


def load_state(path):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except FileNotFoundError:
        return set(), {}
    if not data.strip():
        return set(), {}
    obj = json.loads(data.decode("utf-8"))
    applied = set(obj.get("applied", []))
    balances = {k: int(v) for k, v in obj.get("balances", {}).items()}
    return applied, balances


def save_state(path, applied, balances):
    data = json.dumps(
        {"applied": sorted(applied), "balances": balances},
        ensure_ascii=True,
        separators=(",", ":"),
    ).encode("utf-8")
    with open(path, "wb") as f:
        f.write(data)
        f.flush()
        try:
            os.fsync(f.fileno())
        except OSError:
            pass


def parse_event(raw):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        obj = json.loads(text)
    except (ValueError, RecursionError):
        return None
    if not isinstance(obj, dict):
        return None
    eid = obj.get("id")
    acct = obj.get("account")
    cents = obj.get("cents")
    if not isinstance(eid, str) or not isinstance(acct, str):
        return None
    if not isinstance(cents, int) or isinstance(cents, bool):
        return None
    return eid, acct, cents


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]

    applied, balances = load_state(state_path)

    with open(os.path.join(input_dir, "events.jsonl"), "rb") as f:
        content = f.read()

    n_applied = n_dup = n_rej = 0
    for raw in content.split(b"\n"):
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        if not raw.strip():
            continue
        ev = parse_event(raw)
        if ev is None:
            n_rej += 1
            continue
        eid, acct, cents = ev
        if eid in applied:
            n_dup += 1
            continue
        applied.add(eid)
        balances[acct] = balances.get(acct, 0) + cents
        n_applied += 1

    save_state(state_path, applied, balances)

    out = ["applied %d duplicate %d rejected %d" % (n_applied, n_dup, n_rej)]
    for acct in sorted(balances, key=lambda a: a.encode("utf-8", "surrogatepass")):
        out.append("%s %d" % (acct, balances[acct]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

