import os
import json

def main():
    input_dir = os.environ["INPUT"]
    board_path = os.environ["BOARD"]

    totals = {}
    try:
        with open(board_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            for name, v in data.items():
                if isinstance(v, list) and len(v) == 2:
                    totals[name] = [int(v[0]), int(v[1])]
    except FileNotFoundError:
        pass
    except (ValueError, OSError):
        pass

    def add(name, pts):
        rec = totals.setdefault(name, [0, 0])
        rec[0] += pts
        rec[1] += 1

    path = os.path.join(input_dir, "games.txt")
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        raw = b""
    text = raw.decode("utf-8", errors="surrogateescape")

    for line in text.splitlines():
        parts = line.split()
        if len(parts) == 2:
            w, l = parts
            add(w, 3)
            add(l, 0)
        elif len(parts) == 3 and parts[2] == "draw":
            a, b = parts[0], parts[1]
            add(a, 1)
            add(b, 1)

    tmp = board_path + ".tmp"
    with open(tmp, "w", encoding="utf-8", errors="surrogateescape") as f:
        json.dump(totals, f, ensure_ascii=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, board_path)

    ranked = sorted(
        totals.items(),
        key=lambda kv: (-kv[1][0], kv[1][1],
                        kv[0].encode("utf-8", errors="surrogateescape")),
    )
    for i, (name, (pts, played)) in enumerate(ranked[:3], 1):
        print(f"{i}. {name} {pts} {played}")

