import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV_PATH = os.environ["COUNTS"]
PORT = int(os.environ["PORT"])
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")

lock = threading.Lock()


def load():
    try:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {str(k): int(v) for k, v in data.items()}
    except (OSError, ValueError, TypeError):
        pass
    return {}


counts = load()


def save():
    with open(KV_PATH, "w", encoding="utf-8") as f:
        json.dump(counts, f)
        f.flush()
        try:
            os.fsync(f.fileno())
        except OSError:
            pass


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def drain(self):
        n = self.headers.get("content-length")
        if n:
            try:
                n = int(n)
                if n > 0:
                    self.rfile.read(n)
            except ValueError:
                pass

    def handle_any(self):
        self.drain()
        path = self.path
        method = self.command
        if method == "POST" and path.startswith("/hit/"):
            name = path[len("/hit/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                counts[name] = counts.get(name, 0) + 1
                n = counts[name]
                save()
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path.startswith("/count/"):
            name = path[len("/count/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                n = counts.get(name, 0)
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path == "/top":
            with lock:
                items = sorted(
                    counts.items(),
                    key=lambda kv: (-kv[1], kv[0].encode("utf-8")),
                )[:3]
            return self.send_json(
                200, [{"name": k, "count": v} for k, v in items]
            )
        return self.send_json(404, {"error": "not found"})

    do_GET = handle_any
    do_POST = handle_any
    do_PUT = handle_any
    do_DELETE = handle_any
    do_PATCH = handle_any
    do_HEAD = handle_any
    do_OPTIONS = handle_any
    do_TRACE = handle_any
    do_CONNECT = handle_any


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ["STORE"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and "next" in data and "todos" in data:
            return data
    except Exception:
        pass
    return {"next": 1, "todos": []}


def save(data):
    with open(STORE, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())


def parse_id(s):
    if not s or not s.isdigit() or not s.isascii():
        return None
    return int(s)


def find(data, tid):
    for t in data["todos"]:
        if t["id"] == tid:
            return t
    return None


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def __getattr__(self, name):
        if name.startswith("do_"):
            return self.dispatch
        raise AttributeError(name)

    def send(self, status, obj=None):
        self.send_response(status)
        if obj is None:
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        body = json.dumps(obj).encode("utf-8")
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def read_body(self):
        n = self.headers.get("Content-Length")
        try:
            n = int(n) if n else 0
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def parse_json(self, raw):
        try:
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def dispatch(self):
        raw = self.read_body()
        u = urlsplit(self.path)
        path = u.path
        method = self.command
        with LOCK:
            data = load()
            if path == "/todos":
                if method == "GET":
                    todos = sorted(data["todos"], key=lambda t: t["id"])
                    q = parse_qs(u.query)
                    if "done" in q:
                        v = q["done"][0]
                        if v == "true":
                            todos = [t for t in todos if t["done"] is True]
                        elif v == "false":
                            todos = [t for t in todos if t["done"] is False]
                    return self.send(200, todos)
                if method == "POST":
                    body = self.parse_json(raw)
                    if not isinstance(body, dict):
                        return self.send(400, {"error": "title required"})
                    title = body.get("title")
                    if not isinstance(title, str) or not title.strip():
                        return self.send(400, {"error": "title required"})
                    todo = {"id": data["next"], "title": title.strip(), "done": False}
                    data["next"] += 1
                    data["todos"].append(todo)
                    save(data)
                    return self.send(201, todo)
                return self.send(404, {"error": "not found"})
            if path.startswith("/todos/"):
                tid = parse_id(path[len("/todos/"):])
                todo = find(data, tid) if tid is not None else None
                if method not in ("GET", "PATCH", "DELETE") or todo is None:
                    return self.send(404, {"error": "not found"})
                if method == "GET":
                    return self.send(200, todo)
                if method == "DELETE":
                    data["todos"] = [t for t in data["todos"] if t["id"] != tid]
                    save(data)
                    return self.send(204)
                body = self.parse_json(raw)
                if not isinstance(body, dict):
                    return self.send(400, {"error": "bad update"})
                upd = {}
                if "title" in body:
                    t = body["title"]
                    if not isinstance(t, str) or not t.strip():
                        return self.send(400, {"error": "bad update"})
                    upd["title"] = t.strip()
                if "done" in body:
                    d = body["done"]
                    if not isinstance(d, bool):
                        return self.send(400, {"error": "bad update"})
                    upd["done"] = d
                todo.update(upd)
                save(data)
                return self.send(200, todo)
            return self.send(404, {"error": "not found"})


if __name__ == "__main__":
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()

import os
import json
import sqlite3
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
PORT = int(os.environ["PORT"])

conn = sqlite3.connect(DB_PATH, check_same_thread=False)
conn.execute(
    "CREATE TABLE IF NOT EXISTS notes ("
    "id INTEGER PRIMARY KEY AUTOINCREMENT, "
    "title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"
)
conn.commit()
lock = threading.Lock()

NOT_FOUND = (404, {"error": "not found"})


def parse_id(s):
    if s and s.isascii() and s.isdigit():
        return int(s)
    return None


def create(raw):
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        return 400, {"error": "invalid note"}
    if not isinstance(data, dict):
        return 400, {"error": "invalid note"}
    title = data.get("title")
    body = data.get("body")
    tags = data.get("tags", [])
    if not isinstance(title, str) or title == "":
        return 400, {"error": "invalid note"}
    if not isinstance(body, str):
        return 400, {"error": "invalid note"}
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        return 400, {"error": "invalid note"}
    seen = []
    for t in tags:
        t = t.lower()
        if t not in seen:
            seen.append(t)
    with lock:
        cur = conn.execute(
            "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)",
            (title, body, json.dumps(seen)),
        )
        conn.commit()
        nid = cur.lastrowid
    return 201, {"id": nid}


def get_one(nid):
    with lock:
        row = conn.execute(
            "SELECT id, title, body, tags FROM notes WHERE id = ?", (nid,)
        ).fetchone()
    if row is None:
        return NOT_FOUND
    return 200, {"id": row[0], "title": row[1], "body": row[2], "tags": json.loads(row[3])}


def list_notes(query):
    qs = parse_qs(query, keep_blank_values=True)
    tag = qs.get("tag", [None])[0]
    q = qs.get("q", [None])[0]
    if tag is not None:
        tag = tag.lower()
    with lock:
        rows = conn.execute(
            "SELECT id, title, body, tags FROM notes ORDER BY id DESC"
        ).fetchall()
    out = []
    for r in rows:
        if tag is not None and tag not in json.loads(r[3]):
            continue
        if q is not None and q not in r[1] and q not in r[2]:
            continue
        out.append({"id": r[0], "title": r[1]})
    return 200, out


def delete(nid):
    with lock:
        cur = conn.execute("DELETE FROM notes WHERE id = ?", (nid,))
        conn.commit()
        n = cur.rowcount
    if n == 0:
        return NOT_FOUND
    return 200, {"deleted": nid}


def route(method, target, raw):
    try:
        parts = urlsplit(target)
    except Exception:
        return NOT_FOUND
    path = parts.path
    if path == "/notes":
        if method == "POST":
            return create(raw)
        if method == "GET":
            return list_notes(parts.query)
        return NOT_FOUND
    if path.startswith("/notes/"):
        nid = parse_id(path[len("/notes/"):])
        if nid is None:
            return NOT_FOUND
        if method == "GET":
            return get_one(nid)
        if method == "DELETE":
            return delete(nid)
        return NOT_FOUND
    return NOT_FOUND


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def _handle(self):
        length = self.headers.get("Content-Length")
        raw = b""
        if length:
            try:
                raw = self.rfile.read(int(length))
            except Exception:
                raw = b""
        try:
            status, obj = route(self.command, self.path, raw)
        except Exception:
            status, obj = 500, {"error": "internal error"}
        payload = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(payload)

    do_GET = _handle
    do_POST = _handle
    do_DELETE = _handle
    do_PUT = _handle
    do_PATCH = _handle
    do_HEAD = _handle
    do_OPTIONS = _handle
    do_TRACE = _handle
    do_CONNECT = _handle


if __name__ == "__main__":
    server = HTTPServer(("127.0.0.1", PORT), Handler)
    server.serve_forever()

import json
import os
import sys


def tarjan(nodes, adj):
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    counter = 0
    for root in nodes:
        if root in index:
            continue
        work = [(root, 0)]
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        while work:
            v, i = work[-1]
            nbrs = adj[v]
            if i < len(nbrs):
                work[-1] = (v, i + 1)
                w = nbrs[i]
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, 0))
                elif w in onstack:
                    if index[w] < low[v]:
                        low[v] = index[w]
            else:
                work.pop()
                if work:
                    u = work[-1][0]
                    if low[v] < low[u]:
                        low[u] = low[v]
                if low[v] == index[v]:
                    comp = []
                    while True:
                        w = stack.pop()
                        onstack.discard(w)
                        comp.append(w)
                        if w == v:
                            break
                    sccs.append(comp)
    return sccs


def main():
    out = []
    path = os.path.join(os.environ["INPUT"], "packages.json")
    try:
        with open(path, "rb") as f:
            data = json.loads(f.read())
    except Exception:
        data = None
    if not isinstance(data, dict):
        sys.stdout.buffer.write(b"error: not an object\n")
        return

    valid = {}
    invalid = []
    for name, deps in data.items():
        if isinstance(deps, list) and all(isinstance(d, str) for d in deps):
            seen = []
            s = set()
            for d in deps:
                if d not in s:
                    s.add(d)
                    seen.append(d)
            valid[name] = seen
        else:
            invalid.append(name)

    missing = {}
    adj = {}
    for p, deps in valid.items():
        adj[p] = [d for d in deps if d in valid]
        for d in deps:
            if d not in valid:
                missing.setdefault(d, set()).add(p)

    nodes = sorted(valid)
    sccs = tarjan(nodes, adj)

    in_cycle = set()
    cycles = []
    for comp in sccs:
        if len(comp) > 1 or (comp[0] in valid[comp[0]]):
            cycles.append(sorted(comp))
            in_cycle.update(comp)

    stage = {}
    for comp in sccs:  # reverse topological order: dependencies first
        if len(comp) != 1:
            continue
        p = comp[0]
        if p in in_cycle:
            continue
        ok = True
        st = 1
        for d in valid[p]:
            if d not in valid or d not in stage:
                ok = False
                break
            if stage[d] + 1 > st:
                st = stage[d] + 1
        if ok:
            stage[p] = st

    by_stage = {}
    for p, s in stage.items():
        by_stage.setdefault(s, []).append(p)
    for s in sorted(by_stage):
        out.append("stage %d: %s" % (s, ", ".join(sorted(by_stage[s]))))

    cycles.sort(key=lambda c: c[0])
    for c in cycles:
        out.append("cycle: " + ", ".join(c))

    for m in sorted(missing):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m]))))

    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid)))

    blocked = sorted(p for p in valid if p not in stage and p not in in_cycle)
    if blocked:
        out.append("blocked: " + ", ".join(blocked))

    out.append("built %d of %d" % (len(stage), len(valid)))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))


main()

import os
import sys


def parse_time(s, allow_24):
    if len(s) != 5 or s[2] != ":":
        return None
    hh, mm = s[:2], s[3:]
    if not (hh.isascii() and hh.isdigit() and mm.isascii() and mm.isdigit()):
        return None
    h, m = int(hh), int(mm)
    if allow_24 and h == 24 and m == 0:
        return 1440
    if h > 23 or m > 59:
        return None
    return h * 60 + m


def fmt(t):
    return "%02d:%02d" % (t // 60, t % 60)


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "bookings.csv")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", errors="replace")
    lines = data.split("\n")
    skipped = []
    seen = set()
    groups = {}
    for idx, raw in enumerate(lines, start=1):
        line = raw[:-1] if raw.endswith("\r") else raw
        if idx == 1:
            continue
        if line.strip() == "":
            continue
        fields = line.split(",")
        if len(fields) != 5:
            skipped.append(idx)
            continue
        room, day, st, en, who = fields
        s = parse_time(st, False)
        e = parse_time(en, True)
        if s is None or e is None or e <= s:
            skipped.append(idx)
            continue
        key = tuple(fields)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault((room, day), []).append((s, e, who))

    out = []
    keys = sorted(groups.keys(), key=lambda k: (k[0].encode("utf-8"), k[1].encode("utf-8")))
    for room, day in keys:
        bs = groups[(room, day)]
        out.append("%s %s" % (room, day))
        ivs = sorted((s, e) for s, e, _ in bs)
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
        free = []
        cur = 540
        for s, e in merged:
            if e <= cur:
                continue
            if s >= 1080:
                break
            if s > cur:
                free.append((cur, min(s, 1080)))
            cur = max(cur, e)
            if cur >= 1080:
                break
        if cur < 1080:
            free.append((cur, 1080))
        free = [(s, e) for s, e in free if e - s >= 30]
        if free:
            out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in free))
        else:
            out.append("  free none")
        conflicts = []
        n = len(bs)
        for i in range(n):
            for j in range(i + 1, n):
                s1, e1, w1 = bs[i]
                s2, e2, w2 = bs[j]
                os_ = max(s1, s2)
                oe = min(e1, e2)
                if oe - os_ >= 1:
                    names = sorted([w1, w2], key=lambda x: x.encode("utf-8"))
                    text = "  conflict %s/%s %s-%s" % (names[0], names[1], fmt(os_), fmt(oe))
                    conflicts.append((os_, text.encode("utf-8"), text))
        conflicts.sort(key=lambda c: (c[0], c[1]))
        for c in conflicts:
            out.append(c[2])
    if skipped:
        out.append("skipped: " + ", ".join(str(x) for x in skipped))
    else:
        out.append("skipped: none")
    sys.stdout.write("\n".join(out) + "\n")


