import json
import os
import sys


class BadJSON(Exception):
    pass


def _bad_constant(name):
    raise BadJSON(name)


def type_name(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, float):
        return "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "unknown"


def matches(t, v):
    tn = type_name(v)
    if t == "number":
        return tn in ("integer", "number")
    return tn == t


def validate(schema, v, path, errs):
    t = schema.get("type")
    if not matches(t, v):
        errs.append((path, "expected %s" % t))
        return
    if t == "object":
        props = schema.get("properties", {}) or {}
        for r in schema.get("required", []) or []:
            if r not in v:
                errs.append((path + "." + r, "missing required field"))
        additional = schema.get("additional", True)
        for k, sub in v.items():
            if k in props:
                validate(props[k], sub, path + "." + k, errs)
            elif additional is False:
                errs.append((path + "." + k, "unexpected field"))
    elif t == "array":
        mi = schema.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d items" % mi))
        it = schema.get("items")
        if it is not None:
            for i, e in enumerate(v):
                validate(it, e, "%s[%d]" % (path, i), errs)
    elif t == "string":
        n = len(v)
        mn = schema.get("min_length")
        mx = schema.get("max_length")
        en = schema.get("enum")
        if mn is not None and n < mn:
            errs.append((path, "shorter than %d" % mn))
        elif mx is not None and n > mx:
            errs.append((path, "longer than %d" % mx))
        elif en is not None and v not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        mn = schema.get("minimum")
        mx = schema.get("maximum")
        if mn is not None and v < mn:
            errs.append((path, "less than %d" % mn))
        elif mx is not None and v > mx:
            errs.append((path, "greater than %d" % mx))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "schema.json"), "r", encoding="utf-8") as f:
        schema = json.load(f)
    with open(os.path.join(d, "records.jsonl"), "rb") as f:
        data = f.read().decode("utf-8", errors="surrogateescape")
    lines = data.split("\n")
    out = []
    valid = 0
    total = 0
    for idx, line in enumerate(lines, 1):
        if line.strip() == "":
            continue
        total += 1
        try:
            rec = json.loads(line, parse_constant=_bad_constant)
        except Exception:
            out.append("line %d: invalid JSON" % idx)
            continue
        errs = []
        validate(schema, rec, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % idx)
            continue
        errs.sort(key=lambda e: (e[0].encode("utf-8", "surrogateescape"),
                                 e[1].encode("utf-8", "surrogateescape")))
        for p, m in errs:
            out.append("line %d: %s: %s" % (idx, p, m))
    out.append("valid %d of %d" % (valid, total))
    sys.stdout.write("\n".join(out) + "\n")


main()

import json
import os
import sys


class BadConstant(Exception):
    pass


def _reject_constant(name):
    raise BadConstant(name)


class Flt:
    """Marks a number written with a fraction or exponent."""
    __slots__ = ("v",)

    def __init__(self, s):
        self.v = float(s)


def parse(text):
    return json.loads(text, parse_float=Flt, parse_constant=_reject_constant)


def type_of(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, Flt):
        return "float"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "unknown"


def matches(t, v):
    vt = type_of(v)
    if t == "number":
        return vt in ("integer", "float")
    return vt == t


def num(v):
    return v.v if isinstance(v, Flt) else v


def validate(schema, v, path, errs):
    t = schema.get("type")
    if not matches(t, v):
        errs.append((path, "expected " + str(t)))
        return
    if t == "object":
        props = schema.get("properties", {}) or {}
        for name in schema.get("required", []) or []:
            if name not in v:
                errs.append((path + "." + name, "missing required field"))
        additional = schema.get("additional", True)
        for name, val in v.items():
            if name in props:
                validate(props[name], val, path + "." + name, errs)
            elif additional is False:
                errs.append((path + "." + name, "unexpected field"))
    elif t == "array":
        mi = schema.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d" % mi + " items"))
        item_schema = schema.get("items")
        if item_schema is not None:
            for i, el in enumerate(v):
                validate(item_schema, el, "%s[%d]" % (path, i), errs)
    elif t == "string":
        n = len(v)
        mn = schema.get("min_length")
        mx = schema.get("max_length")
        en = schema.get("enum")
        if mn is not None and n < mn:
            errs.append((path, "shorter than %s" % mn))
        elif mx is not None and n > mx:
            errs.append((path, "longer than %s" % mx))
        elif en is not None and v not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        x = num(v)
        mn = schema.get("minimum")
        mx = schema.get("maximum")
        if mn is not None and x < mn:
            errs.append((path, "less than %s" % mn))
        elif mx is not None and x > mx:
            errs.append((path, "greater than %s" % mx))


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "schema.json"), "r", encoding="utf-8") as f:
        schema = json.load(f)
    with open(os.path.join(base, "records.jsonl"), "rb") as f:
        data = f.read()

    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    out = []
    valid = 0
    total = 0
    for idx, raw in enumerate(lines, 1):
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            text = None
        if text is not None and text.strip() == "":
            continue
        if text is None and raw.strip() == b"":
            continue
        total += 1
        try:
            if text is None:
                raise ValueError("bad utf-8")
            value = parse(text)
        except (ValueError, BadConstant, RecursionError):
            out.append("line %d: invalid JSON" % idx)
