import json
import os


def check(schema, value, path, errs):
    t = schema.get("type")
    if t == "object":
        if not isinstance(value, dict):
            errs.append((path, "expected object"))
            return
        props = schema.get("properties", {}) or {}
        for name in schema.get("required", []) or []:
            if name not in value:
                errs.append((path + "." + name, "missing required field"))
        additional = schema.get("additional", True)
        for k, v in value.items():
            if k in props:
                check(props[k], v, path + "." + k, errs)
            elif additional is False:
                errs.append((path + "." + k, "unexpected field"))
    elif t == "array":
        if not isinstance(value, list):
            errs.append((path, "expected array"))
            return
        mi = schema.get("min_items")
        if mi is not None and len(value) < mi:
            errs.append((path, "fewer than %d items" % mi))
        items = schema.get("items")
        if items is not None:
            for i, v in enumerate(value):
                check(items, v, "%s[%d]" % (path, i), errs)
    elif t == "string":
        if not isinstance(value, str):
            errs.append((path, "expected string"))
            return
        n = len(value)
        mn = schema.get("min_length")
        mx = schema.get("max_length")
        en = schema.get("enum")
        if mn is not None and n < mn:
            errs.append((path, "shorter than %d" % mn))
        elif mx is not None and n > mx:
            errs.append((path, "longer than %d" % mx))
        elif en is not None and value not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        if isinstance(value, bool):
            ok = False
        elif t == "integer":
            ok = isinstance(value, int)
        else:
            ok = isinstance(value, (int, float))
        if not ok:
            errs.append((path, "expected " + t))
            return
        mn = schema.get("minimum")
        mx = schema.get("maximum")
        if mn is not None and value < mn:
            errs.append((path, "less than %d" % mn))
        elif mx is not None and value > mx:
            errs.append((path, "greater than %d" % mx))
    elif t == "boolean":
        if not isinstance(value, bool):
            errs.append((path, "expected boolean"))
    elif t == "null":
        if value is not None:
            errs.append((path, "expected null"))


def bad_constant(s):
    raise ValueError("invalid constant " + s)


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "schema.json"), encoding="utf-8") as f:
        schema = json.load(f)
    with open(os.path.join(base, "records.jsonl"), encoding="utf-8", newline="") as f:
        text = f.read()
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    valid = 0
    total = 0
    out = []
    for i, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        total += 1
        try:
            value = json.loads(line, parse_constant=bad_constant)
        except ValueError:
            out.append("line %d: invalid JSON" % i)
            continue
        errs = []
        check(schema, value, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % i)
        else:
            errs.sort(key=lambda e: (e[0].encode("utf-8"), e[1].encode("utf-8")))
            for p, m in errs:
                out.append("line %d: %s: %s" % (i, p, m))
    out.append("valid %d of %d" % (valid, total))
    print("\n".join(out))


