        if (
            not isinstance(obj, dict)
            or not isinstance(obj.get("id"), str)
            or not isinstance(obj.get("version"), int)
            or isinstance(obj.get("version"), bool)
        ):
            invalid.append(i)
            continue
        records[obj["id"]] = (obj, line.strip())

    state = load_state(state_path)
    opener = urllib.request.build_opener(NoRedirect)

    results = {}
    to_push = []
    for rid in records:
        obj, _ = records[rid]
        last = state.get(rid)
        if isinstance(last, int) and not isinstance(last, bool) and obj["version"] <= last:
            results[rid] = ("unchanged", None)
        else:
            to_push.append(rid)

    pending = list(to_push)
    for attempt in range(3):
        if not pending:
            break
        retry = []
        for rid in pending:
            obj, line = records[rid]
            status = put(opener, base, rid, line.encode("utf-8"))
            if status is not None and 200 <= status < 300:
                results[rid] = ("synced", None)
                state[rid] = obj["version"]
                save_state(state_path, state)
            elif status is not None and 400 <= status < 500:
                results[rid] = ("rejected", status)
            else:
                retry.append(rid)
        pending = retry
    for rid in pending:
        results[rid] = ("failed", None)

    save_state(state_path, state)

    out = []
    for n in invalid:
        out.append("line %d invalid" % n)
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8", errors="surrogatepass")):
        kind, st = results[rid]
        counts[kind] += 1
        if kind == "rejected":
            out.append("%s rejected %d" % (rid, st))
        else:
            out.append("%s %s" % (rid, kind))
    out.append(
        "synced %d unchanged %d rejected %d failed %d"
        % (counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"])
    )
    sys.stdout.write("\n".join(out) + "\n")


