            invalid_lines.append(i)
            continue
        if not isinstance(obj, dict):
            invalid_lines.append(i)
            continue
        rid = obj.get("id")
        ver = obj.get("version")
        if not isinstance(rid, str) or not is_int(ver):
            invalid_lines.append(i)
            continue
        records[rid] = (ver, line.encode("utf-8"))

    results = {}  # id -> status string

    for rid in records:
        ver, body = records[rid]
        last = state.get(rid)
        if last is not None and ver <= last:
            results[rid] = "unchanged"
            continue

        outcome = None
        for attempt in range(3):
            st = put(rid, body)
            if st is None or (500 <= st < 600):
                outcome = "failed"
                continue
            if 200 <= st < 300:
                outcome = "synced"
                state[rid] = ver
                break
            if 400 <= st < 500:
                outcome = "rejected %d" % st
                break
            outcome = "failed"
            break
        results[rid] = outcome

    save_state(state)

    for ln in invalid_lines:
        print("line %d invalid" % ln)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
