        elif res.startswith("rejected"):
            counts["rejected"] += 1
        elif res == "failed":
            counts["failed"] += 1

    print("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"],
        counts["rejected"], counts["failed"],
    ))


