        if isinstance(data, dict):
            return {k: v for k, v in data.items() if isinstance(k, str) and is_int(v)}
    except (OSError, ValueError):
        pass
    return {}


def save_state(path, state):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(state, f, sort_keys=True)


def put(base, rid, body):
    url = base.rstrip("/") + "/records/" + urllib.parse.quote(rid, safe="")
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={"content-type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            resp.read()
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"]

    state = load_state(state_path)

    records = {}
    invalid = []
    with open(os.path.join(input_dir, "records.jsonl"), "r", encoding="utf-8") as f:
        lines = f.read().split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    for n, line in enumerate(lines, 1):
        if line.strip() == "":
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            invalid.append(n)
            continue
        if (
            not isinstance(obj, dict)
            or not isinstance(obj.get("id"), str)
            or not is_int(obj.get("version"))
        ):
            invalid.append(n)
            continue
        records[obj["id"]] = obj

    results = {}
    pending = []
    for rid in sorted(records, key=lambda s: s.encode("utf-8")):
        rec = records[rid]
        last = state.get(rid)
        if last is None or rec["version"] > last:
            pending.append(rid)
        else:
            results[rid] = ("unchanged",)

    bodies = {
        rid: json.dumps(records[rid], ensure_ascii=False).encode("utf-8")
        for rid in pending
    }

    for attempt in range(3):
        if not pending:
            break
        retry = []
        for rid in pending:
            status = put(api, rid, bodies[rid])
            if status is not None and 200 <= status < 300:
                results[rid] = ("synced",)
                state[rid] = records[rid]["version"]
            elif status is not None and 400 <= status < 500:
                results[rid] = ("rejected", status)
            else:
                retry.append(rid)
        pending = retry
    for rid in pending:
        results[rid] = ("failed",)

    save_state(state_path, state)

    out = []
    for n in invalid:
        out.append("line %d invalid" % n)
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        r = results[rid]
        counts[r[0]] += 1
        if r[0] == "rejected":
            out.append("%s rejected %d" % (rid, r[1]))
        else:
            out.append("%s %s" % (rid, r[0]))
    out.append(
        "synced %d unchanged %d rejected %d failed %d"
        % (counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"])
    )
    sys.stdout.write("\n".join(out) + "\n")


