import os
import re
import sqlite3
import time

MAX = 9223372036854775807
INT_RE = re.compile(r'^-?[0-9]+$')


def fmt_time(ms):
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(ms // 1000))


def parse_int(s):
    if INT_RE.match(s):
        return int(s)
    return None


def main():
    input_dir = os.environ['INPUT']
    db_path = os.environ['DB']
    log_path = os.environ['LOG']
    clock_ms = int(os.environ['CLOCK'].strip())
    now = fmt_time(clock_ms)

    conn = sqlite3.connect(db_path, isolation_level=None)
    conn.execute('CREATE TABLE IF NOT EXISTS accounts ('
                 'name TEXT PRIMARY KEY, balance INTEGER NOT NULL, '
                 'last TEXT NOT NULL, closed INTEGER NOT NULL DEFAULT 0)')
    conn.execute('CREATE TABLE IF NOT EXISTS transfers ('
                 'id TEXT PRIMARY KEY, frm TEXT NOT NULL, dst TEXT NOT NULL, '
                 'cents TEXT NOT NULL)')

    with open(os.path.join(input_dir, 'ops.txt'), 'rb') as f:
        data = f.read().decode('utf-8')
    lines = data.split('\n')
    if lines and lines[-1] == '':
        lines.pop()

    ok = failed = dup = 0
    log_lines = []

    def get_acct(name):
        return conn.execute('SELECT balance, closed FROM accounts WHERE name=?',
                            (name,)).fetchone()

    def live(name):
        r = get_acct(name)
        if r is None or r[1]:
            return None
        return r[0]

    conn.execute('BEGIN IMMEDIATE')
    try:
        for idx, raw in enumerate(lines, 1):
            line = raw.rstrip('\r')
            if line.strip() == '':
                continue
            w = line.split(' ')
            op = w[0]
            err = None
            is_dup = False
            if op == 'open':
                if len(w) != 3 or parse_int(w[2]) is None:
                    err = 'malformed'
                else:
                    name, amt = w[1], parse_int(w[2])
                    if amt < 0:
                        err = 'bad amount'
                    elif get_acct(name) is not None:
                        err = 'account exists'
                    elif amt > MAX:
                        err = 'overflow'
                    else:
                        conn.execute('INSERT INTO accounts(name,balance,last,closed) '
                                     'VALUES(?,?,?,0)', (name, amt, now))
            elif op == 'transfer':
                if len(w) != 5 or parse_int(w[4]) is None:
                    err = 'malformed'
                else:
                    tid, frm, dst, amt = w[1], w[2], w[3], parse_int(w[4])
                    prev = conn.execute('SELECT frm,dst,cents FROM transfers WHERE id=?',
                                        (tid,)).fetchone()
                    if prev is not None:
                        if prev[0] == frm and prev[1] == dst and int(prev[2]) == amt:
                            is_dup = True
                        else:
                            err = 'id reused'
                    if not is_dup and err is None:
                        if amt <= 0:
                            err = 'bad amount'
                        elif frm == dst:
                            err = 'same account'
                        else:
                            fb = live(frm)
                            if fb is None:
                                err = 'no account ' + frm
                            else:
                                tb = live(dst)
                                if tb is None:
                                    err = 'no account ' + dst
                                elif fb < amt:
                                    err = 'insufficient funds'
                                elif tb + amt > MAX:
                                    err = 'overflow'
                                else:
                                    conn.execute('UPDATE accounts SET balance=?, last=? WHERE name=?',
                                                 (fb - amt, now, frm))
                                    conn.execute('UPDATE accounts SET balance=?, last=? WHERE name=?',
                                                 (tb + amt, now, dst))
                                    conn.execute('INSERT INTO transfers(id,frm,dst,cents) '
                                                 'VALUES(?,?,?,?)', (tid, frm, dst, str(amt)))
            elif op == 'close':
                if len(w) != 2:
                    err = 'malformed'
                else:
                    name = w[1]
                    b = live(name)
                    if b is None:
                        err = 'no account ' + name
                    elif b != 0:
                        err = 'balance not zero'
                    else:
                        conn.execute('UPDATE accounts SET closed=1 WHERE name=?', (name,))
            else:
                err = 'malformed'

            if is_dup:
                dup += 1
            elif err is not None:
                failed += 1
                log_lines.append('%s line %d: %s\n' % (now, idx, err))
            else:
                ok += 1
        conn.execute('COMMIT')
    except BaseException:
        conn.execute('ROLLBACK')
        raise

    if log_lines:
        with open(log_path, 'a', encoding='utf-8') as lf:
            lf.write(''.join(log_lines))

    out = ['ok %d failed %d duplicate %d' % (ok, failed, dup)]
    rows = conn.execute('SELECT name, balance, last FROM accounts WHERE closed=0').fetchall()
    rows.sort(key=lambda r: r[0].encode('utf-8'))
    for name, bal, last in rows:
        out.append('%s %d last %s' % (name, bal, last))
    conn.close()
    print('\n'.join(out))


main()

import os
import json
import hashlib
import hmac
import secrets
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

STORE_PATH = os.environ["STORE"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()

NAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
TOKEN_RE = re.compile(r"^[0-9a-f]{32}$")
SESSION_MS = 30 * 60 * 1000
LOCK_MS = 15 * 60 * 1000


def now_ms():
    return int(os.environ["CLOCK"])


def load():
    try:
        with open(STORE_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError
    except Exception:
        data = {}
    data.setdefault("users", {})
    data.setdefault("sessions", {})
    return data


def save(data):
    raw = json.dumps(data, separators=(",", ":"))
    with open(STORE_PATH, "w", encoding="utf-8") as f:
        f.write(raw)
        f.flush()
        os.fsync(f.fileno())


def hash_pw(salt, name, password):
    h = hashlib.sha256()
    h.update(bytes.fromhex(salt))
    h.update(name.encode("utf-8"))
    h.update(b"\x00")
    h.update(password.encode("utf-8"))
    return h.hexdigest()


def parse_creds(body):
    try:
        obj = json.loads(body.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    name = obj.get("name")
    pw = obj.get("password")
    if not isinstance(name, str) or not isinstance(pw, str):
        return None
    return name, pw


def get_token(headers):
    auth = headers.get("authorization")
    if not auth or not auth.startswith("Bearer "):
        return None
    tok = auth[len("Bearer "):].strip()
    if not TOKEN_RE.match(tok):
        return None
    return tok


def valid_session(data, tok, now):
    if tok is None:
        return None
    s = data["sessions"].get(tok)
    if not s:
        return None
    if now >= s["expires"]:
        del data["sessions"][tok]
        return None
    return s


def handle(method, path, headers, body):
    path = path.split("?", 1)[0]
    now = now_ms()
    with LOCK:
        data = load()
        if method == "POST" and path == "/users":
            c = parse_creds(body)
            if c is None:
                return 400, {"error": "invalid"}
            name, pw = c
            if not NAME_RE.match(name) or len(pw.encode("utf-8")) < 8:
                return 400, {"error": "invalid"}
            if name in data["users"]:
                return 409, {"error": "name taken"}
            salt = secrets.token_hex(16)
            data["users"][name] = {
                "salt": salt,
                "hash": hash_pw(salt, name, pw),
                "logins": 0,
                "fails": 0,
                "locked_until": 0,
            }
            save(data)
            return 201, {"name": name}

        if method == "POST" and path == "/login":
            c = parse_creds(body)
            if c is None:
                return 401, {"error": "bad credentials"}
            name, pw = c
            u = data["users"].get(name)
            if u is None:
                return 401, {"error": "bad credentials"}
            if now < u.get("locked_until", 0):
                return 429, {"error": "locked"}
            if hmac.compare_digest(hash_pw(u["salt"], name, pw), u["hash"]):
                u["fails"] = 0
                u["logins"] = u.get("logins", 0) + 1
                tok = secrets.token_bytes(16).hex()
                data["sessions"][tok] = {"name": name, "expires": now + SESSION_MS}
                # prune expired sessions
                for t in [t for t, s in data["sessions"].items() if now >= s["expires"]]:
                    del data["sessions"][t]
                save(data)
                return 200, {"token": tok, "expires_in": 1800}
            u["fails"] = u.get("fails", 0) + 1
            if u["fails"] >= 3:
                u["fails"] = 0
                u["locked_until"] = now + LOCK_MS
            save(data)
            return 401, {"error": "bad credentials"}

        if method == "GET" and path == "/me":
            tok = get_token(headers)
            s = valid_session(data, tok, now)
            if s is None or s["name"] not in data["users"]:
                save(data)
                return 401, {"error": "unauthorized"}
            s["expires"] = now + SESSION_MS
            save(data)
            u = data["users"][s["name"]]
            return 200, {"name": s["name"], "logins": u.get("logins", 0)}

        if method == "POST" and path == "/logout":
            tok = get_token(headers)
            s = valid_session(data, tok, now)
            if s is None:
                save(data)
                return 401, {"error": "unauthorized"}
            del data["sessions"][tok]
            save(data)
            return 204, None

        return 404, {"error": "not found"}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def _go(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        body = self.rfile.read(n) if n > 0 else b""
        try:
            status, obj = handle(self.command, self.path, self.headers, body)
        except Exception:
            status, obj = 500, {"error": "internal"}
        self.send_response(status)
        if status == 204:
            self.send_header("content-length", "0")
            self.end_headers()
            return
        raw = json.dumps(obj).encode("utf-8")
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = _go


def main():
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    srv.daemon_threads = True
    srv.serve_forever()


if __name__ == "__main__":
    main()

