            newc = cursor if nxt is None else nxt
            conn.execute("INSERT OR REPLACE INTO state (k,v) VALUES ('cursor',?)", (newc,))
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += pa
        stale += ps
        invalid += pi
        if nxt is None:
            end_msg = "complete"
            break
        seen.add(cursor)
        cursor = nxt
        if cursor in seen:
            end_msg = "complete"
            break

    print("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    print(end_msg)
    rows = conn.execute("SELECT sku, qty, name FROM items WHERE present=1").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in rows:
        print("%s %d %s" % (sku, qty, name))
    conn.close()


