import json
import os
import sqlite3
import urllib.error
import urllib.parse
import urllib.request


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def classify(ch):
    if not isinstance(ch, dict):
        return None
    op = ch.get("op")
    sku = ch.get("sku")
    ver = ch.get("version")
    if not isinstance(sku, str) or not is_int(ver):
        return None
    if op == "upsert":
        if isinstance(ch.get("name"), str) and is_int(ch.get("qty")):
            return "upsert"
        return None
    if op == "delete":
        return "delete"
    return None


def fetch(base, cursor):
    url = base.rstrip("/") + "/changes?" + urllib.parse.urlencode({"cursor": cursor})
    req = urllib.request.Request(url, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.status
            body = resp.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None)
    nxt = data.get("next")
    if nxt is not None and not isinstance(nxt, str):
        if is_int(nxt):
            nxt = str(nxt)
        else:
            return ("invalid", None)
    return ("ok", (data["changes"], nxt))


def main():
    base = os.environ["API"]
    conn = sqlite3.connect(os.environ["DB"], isolation_level=None)
    conn.execute("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)")
    row = conn.execute("SELECT v FROM state WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    end_line = None
    while True:
        kind, val = fetch(base, cursor)
        if kind == "status":
            end_line = "stopped at %s (status %d)" % (cursor, val)
            break
        if kind == "noresp":
            end_line = "stopped at %s (no response)" % cursor
            break
        if kind == "invalid":
            end_line = "stopped at %s (invalid page)" % cursor
            break
        changes, nxt = val
        a = s = i = 0
        conn.execute("BEGIN IMMEDIATE")
        try:
            for ch in changes:
                op = classify(ch)
                if op is None:
                    i += 1
