import json
import os


def load_json_file(path, default):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    state = load_json_file(kv_path, None)
    if not isinstance(state, dict) or "jobs" not in state:
        state = {"jobs": {}}
    jobs = state["jobs"]

    out = []

    # Enqueue
    try:
        with open(os.path.join(input_dir, "enqueue.jsonl"), "r", encoding="utf-8") as f:
            text = f.read()
    except OSError:
        text = ""
    for n, line in enumerate(text.split("\n"), start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            obj = None
        if (
            not isinstance(obj, dict)
            or not isinstance(obj.get("id"), str)
            or not isinstance(obj.get("priority"), int)
            or isinstance(obj.get("priority"), bool)
        ):
            out.append("invalid line %d" % n)
            continue
        jid = obj["id"]
        if jid in jobs:
            out.append("duplicate %s" % jid)
            continue
        jobs[jid] = {
            "priority": obj["priority"],
            "due": now,
            "attempts": 0,
            "state": "pending",
        }

    # Work
    script = load_json_file(os.path.join(input_dir, "script.json"), {})
    if not isinstance(script, dict):
        script = {}

    due = [
        jid for jid, j in jobs.items()
        if j["state"] == "pending" and j["due"] <= now
    ]
    due.sort(key=lambda jid: (-jobs[jid]["priority"], jobs[jid]["due"], jid.encode("utf-8")))

    for jid in due[:5]:
        j = jobs[jid]
        j["attempts"] += 1
        a = j["attempts"]
        outcomes = script.get(jid)
        if isinstance(outcomes, list) and outcomes:
            outcome = outcomes[a - 1] if a <= len(outcomes) else outcomes[-1]
        else:
            outcome = "ok"
        if outcome == "fail":
            if a >= 4:
                j["state"] = "dead"
                out.append("dead %s" % jid)
            else:
                s = 60 * (2 ** (a - 1))
                j["due"] = now + s * 1000
                out.append("retry %s in %d" % (jid, s))
        else:
            j["state"] = "done"
            out.append("done %s" % jid)

    counts = {"pending": 0, "done": 0, "dead": 0}
    for j in jobs.values():
        counts[j["state"]] = counts.get(j["state"], 0) + 1
    out.append("pending %d done %d dead %d" % (counts["pending"], counts["done"], counts["dead"]))

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
    os.replace(tmp, kv_path)

    print("\n".join(out))


main()

import os
import sys

MIN = -(1 << 63)
MAX = (1 << 63) - 1


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg


def is_letter(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'


def is_digit(c):
    return '0' <= c <= '9'


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ' or c == '\t':
            i += 1
        elif is_digit(c):
            j = i
            while j < n and is_digit(s[j]):
                j += 1
            toks.append(('INT', s[i:j]))
            i = j
        elif is_letter(c):
            j = i
            while j < n and (is_letter(s[j]) or is_digit(s[j])):
                j += 1
            toks.append(('NAME', s[i:j]))
            i = j
        elif c in '+-*/%^(),=':
            toks.append(('OP', c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else (None, None)

    def take(self):
        tok = self.peek()
        if tok[0] is None:
            raise SyntaxErr()
        self.p += 1
        return tok

    def is_op(self, c):
        k, v = self.peek()
        return k == 'OP' and v == c

    def expect(self, c):
        if not self.is_op(c):
            raise SyntaxErr()
        self.p += 1

    def expr(self):
        node = self.term()
        while self.is_op('+') or self.is_op('-'):
            op = self.take()[1]
            node = ('bin', op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.is_op('*') or self.is_op('/') or self.is_op('%'):
            op = self.take()[1]
            node = ('bin', op, node, self.factor())
        return node

    def factor(self):
        if self.is_op('-'):
            self.p += 1
            return ('neg', self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_op('^'):
            self.p += 1
            return ('bin', '^', a, self.factor())
        return a

    def atom(self):
        k, v = self.take()
        if k == 'INT':
            return ('int', v)
        if k == 'NAME':
            if self.is_op('('):
                self.p += 1
                args = [self.expr()]
                while self.is_op(','):
                    self.p += 1
                    args.append(self.expr())
                self.expect(')')
                return ('call', v, args)
            return ('var', v)
        if k == 'OP' and v == '(':
            e = self.expr()
            self.expect(')')
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr('overflow')
    return v


def ipow(a, b):
    if b < 0:
        raise EvalErr('negative exponent')
    if b == 0:
        return 1
    if a == 0 or a == 1:
        return a
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise EvalErr('overflow')
    return chk(a ** b)


def evaluate(node, env):
    kind = node[0]
    if kind == 'int':
        return chk(int(node[1]))
    if kind == 'var':
        if node[1] not in env:
            raise EvalErr('unknown variable ' + node[1])
        return env[node[1]]
    if kind == 'neg':
        return chk(-evaluate(node[1], env))
    if kind == 'call':
        name, args = node[1], node[2]
        if name in ('min', 'max'):
            want = 2
        elif name == 'abs':
            want = 1
        else:
            raise EvalErr('unknown function ' + name)
        if len(args) != want:
            raise EvalErr('wrong number of arguments to ' + name)
        vals = [evaluate(a, env) for a in args]
        if name == 'min':
            return min(vals)
        if name == 'max':
            return max(vals)
        return chk(abs(vals[0]))
    if kind == 'bin':
        op = node[1]
        a = evaluate(node[2], env)
        b = evaluate(node[3], env)
        if op == '+':
            return chk(a + b)
        if op == '-':
            return chk(a - b)
        if op == '*':
            return chk(a * b)
        if op == '/' or op == '%':
            if b == 0:
                raise EvalErr('division by zero')
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            if op == '/':
                return chk(q)
            r = abs(a) % abs(b)
            if a < 0:
                r = -r
            return chk(r)
        if op == '^':
            return ipow(a, b)
    raise SyntaxErr()


def parse_line(line):
    toks = tokenize(line)
    if toks and toks[0] == ('NAME', 'let'):
        if len(toks) < 2 or toks[1][0] != 'NAME':
            raise SyntaxErr()
        p = Parser(toks)
        p.p = 2
        p.expect('=')
        e = p.expr()
        if p.p != len(toks):
            raise SyntaxErr()
        return ('let', toks[1][1], e)
    p = Parser(toks)
    e = p.expr()
    if p.p != len(toks):
        raise SyntaxErr()
    return ('expr', e)


def main():
    sys.setrecursionlimit(20000)
    d = os.environ['INPUT']
    with open(os.path.join(d, 'program.txt'), 'rb') as f:
        data = f.read().decode('utf-8', errors='replace')
    lines = data.split('\n')
    env = {}
    out = []
    for idx, raw in enumerate(lines, 1):
        line = raw.rstrip('\r')
        if line.strip(' \t') == '':
            continue
        try:
            try:
                stmt = parse_line(line)
            except RecursionError:
                raise SyntaxErr()
            if stmt[0] == 'let':
                v = evaluate(stmt[2], env)
                env[stmt[1]] = v
                out.append('%d: %s = %d' % (idx, stmt[1], v))
            else:
                v = evaluate(stmt[1], env)
                out.append('%d: %d' % (idx, v))
        except SyntaxErr:
            out.append('%d: error: syntax error' % idx)
        except EvalErr as e:
            out.append('%d: error: %s' % (idx, e.msg))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


main()

import os
import string

MIN = -9223372036854775808
MAX = 9223372036854775807
DIGITS = "0123456789"
START = string.ascii_letters + "_"
CONT = START + DIGITS
FUNCS = {"min": 2, "max": 2, "abs": 1}


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg


def tokenize(s):
    toks = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c in " \t\r":
            i += 1
        elif c in DIGITS:
            j = i
            while j < n and s[j] in DIGITS:
                j += 1
            toks.append(("INT", s[i:j]))
            i = j
        elif c in START:
            j = i
            while j < n and s[j] in CONT:
                j += 1
            toks.append(("NAME", s[i:j]))
            i = j
        elif c in "+-*/%^(),=":
            toks.append((c, c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0] if self.i < len(self.t) else None

    def take(self, kind=None):
        if self.i >= len(self.t):
            raise SyntaxErr()
        tok = self.t[self.i]
        if kind is not None and tok[0] != kind:
            raise SyntaxErr()
        self.i += 1
        return tok

    def expr(self):
        node = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()[0]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.peek() in ("*", "/", "%"):
            op = self.take()[0]
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == "^":
            self.take()
            return ("bin", "^", base, self.factor())
        return base

    def atom(self):
        k = self.peek()
        if k == "INT":
            return ("int", self.take()[1])
        if k == "NAME":
            name = self.take()[1]
            if self.peek() == "(":
                self.take()
                args = [self.expr()]
                while self.peek() == ",":
                    self.take()
                    args.append(self.expr())
                self.take(")")
                return ("call", name, args)
            return ("var", name)
        if k == "(":
            self.take()
            e = self.expr()
            self.take(")")
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr("overflow")
    return v


def evaluate(node, env):
    k = node[0]
    if k == "int":
        return chk(int(node[1]))
    if k == "var":
        if node[1] not in env:
            raise EvalErr("unknown variable " + node[1])
        return env[node[1]]
    if k == "neg":
        return chk(-evaluate(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise EvalErr("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise EvalErr("wrong number of arguments to " + name)
        vals = [evaluate(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    if k == "bin":
        op = node[1]
        a = evaluate(node[2], env)
        b = evaluate(node[3], env)
        if op == "+":
            return chk(a + b)
        if op == "-":
            return chk(a - b)
        if op == "*":
            return chk(a * b)
        if op in ("/", "%"):
            if b == 0:
                raise EvalErr("division by zero")
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            if op == "/":
                return chk(q)
            return chk(a - b * q)
        if op == "^":
            if b < 0:
                raise EvalErr("negative exponent")
            if abs(a) <= 1:
                return chk(pow(a, b))
            if b >= 64:
                raise EvalErr("overflow")
            return chk(pow(a, b))
    raise EvalErr("internal")


def main():
    path = os.path.join(os.environ["INPUT"], "program.txt")
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        text = f.read()
    env = {}
    out = []
    for lineno, raw in enumerate(text.split("\n"), 1):
        line = raw.rstrip("\r")
        if line.strip(" \t") == "":
            continue
        try:
            toks = tokenize(line)
            is_let = bool(toks) and toks[0] == ("NAME", "let")
            p = Parser(toks)
            name = None
            if is_let:
                p.take()
                name = p.take("NAME")[1]
                p.take("=")
            tree = p.expr()
            if p.i != len(toks):
                raise SyntaxErr()
        except SyntaxErr:
            out.append("%d: error: syntax error" % lineno)
            continue
        try:
            v = evaluate(tree, env)
        except EvalErr as e:
            out.append("%d: error: %s" % (lineno, e.msg))
            continue
        if name is not None:
            env[name] = v
            out.append("%d: %s = %d" % (lineno, name, v))
        else:
            out.append("%d: %d" % (lineno, v))
    print("\n".join(out))


main()

import os
import sys

sys.setrecursionlimit(100000)

MIN = -9223372036854775808
MAX = 9223372036854775807


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    pass


def is_letter(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'


def is_digit(c):
    return '0' <= c <= '9'


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\r':
            i += 1
        elif is_digit(c):
            j = i
            while j < n and is_digit(s[j]):
                j += 1
            toks.append(('INT', s[i:j]))
            i = j
        elif is_letter(c):
            j = i
            while j < n and (is_letter(s[j]) or is_digit(s[j])):
                j += 1
            toks.append(('NAME', s[i:j]))
            i = j
        elif c in '+-*/%^(),=':
            toks.append((c, c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self, k=0):
        if self.i + k < len(self.t):
            return self.t[self.i + k][0]
        return None

    def next(self):
        if self.i >= len(self.t):
            raise SyntaxErr()
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect(self, kind):
        tok = self.next()
        if tok[0] != kind:
            raise SyntaxErr()
        return tok

    def line(self):
        if self.peek() == 'NAME' and self.t[0][1] == 'let':
            self.next()
            name = self.expect('NAME')[1]
            self.expect('=')
            e = self.expr()
            if self.i != len(self.t):
                raise SyntaxErr()
            return ('let', name, e)
        e = self.expr()
        if self.i != len(self.t):
            raise SyntaxErr()
        return ('expr', e)

    def expr(self):
        left = self.term()
        while self.peek() in ('+', '-'):
            op = self.next()[0]
            right = self.term()
            left = ('bin', op, left, right)
        return left

    def term(self):
        left = self.factor()
        while self.peek() in ('*', '/', '%'):
            op = self.next()[0]
            right = self.factor()
            left = ('bin', op, left, right)
        return left

    def factor(self):
        if self.peek() == '-':
            self.next()
            return ('neg', self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.peek() == '^':
            self.next()
            b = self.factor()
            return ('bin', '^', a, b)
        return a

    def atom(self):
        tok = self.next()
        if tok[0] == 'INT':
            return ('int', tok[1])
        if tok[0] == 'NAME':
            if self.peek() == '(':
                self.next()
                args = [self.expr()]
                while self.peek() == ',':
                    self.next()
                    args.append(self.expr())
                self.expect(')')
                return ('call', tok[1], args)
            return ('var', tok[1])
        if tok[0] == '(':
            e = self.expr()
            self.expect(')')
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr('overflow')
    return v


def ipow(a, b):
    if b < 0:
        raise EvalErr('negative exponent')
    if b == 0:
        return 1
    if a == 0:
        return 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise EvalErr('overflow')
    return chk(a ** b)


FUNCS = {'min': 2, 'max': 2, 'abs': 1}


def ev(node, env):
    k = node[0]
    if k == 'int':
        return chk(int(node[1]))
    if k == 'var':
        if node[1] not in env:
            raise EvalErr('unknown variable ' + node[1])
        return env[node[1]]
    if k == 'neg':
        return chk(-ev(node[1], env))
    if k == 'call':
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise EvalErr('unknown function ' + name)
        if len(args) != FUNCS[name]:
            raise EvalErr('wrong number of arguments to ' + name)
        vals = [ev(a, env) for a in args]
        if name == 'min':
            return min(vals)
        if name == 'max':
            return max(vals)
        return chk(abs(vals[0]))
    if k == 'bin':
        op = node[1]
        a = ev(node[2], env)
        b = ev(node[3], env)
        if op == '+':
            return chk(a + b)
        if op == '-':
            return chk(a - b)
        if op == '*':
            return chk(a * b)
        if op in ('/', '%'):
            if b == 0:
                raise EvalErr('division by zero')
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            if op == '/':
                return chk(q)
            return chk(a - b * q)
        if op == '^':
            return ipow(a, b)
    raise EvalErr('syntax error')


def main():
    d = os.environ['INPUT']
    with open(os.path.join(d, 'program.txt'), encoding='utf-8', errors='replace') as f:
        text = f.read()
    env = {}
    out = []
    for idx, raw in enumerate(text.split('\n'), 1):
        line = raw.rstrip('\r')
        if line.strip(' \t\r') == '':
            continue
        try:
            try:
                tree = Parser(tokenize(line)).line()
            except SyntaxErr:
                raise EvalErr('syntax error')
            if tree[0] == 'let':
                v = ev(tree[2], env)
                env[tree[1]] = v
                out.append('%d: %s = %d' % (idx, tree[1], v))
            else:
                v = ev(tree[1], env)
                out.append('%d: %d' % (idx, v))
        except EvalErr as e:
            out.append('%d: error: %s' % (idx, e.args[0]))
        except RecursionError:
            out.append('%d: error: syntax error' % idx)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


main()

import os, json, sqlite3, hashlib, hmac, threading
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import unquote

DB_PATH = os.environ["DB"]
SECRETS = os.environ["SECRETS"]
LOG_PATH = os.environ["LOG"]
PORT = int(os.environ["PORT"])

LOCK = threading.Lock()

TYPES = {"subscription.created", "subscription.activated",
         "payment.failed", "subscription.canceled"}
TRANS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}


def load_secret():
    with open(os.path.join(SECRETS, "webhook.key"), "rb") as f:
        s = f.read()
    if s.endswith(b"\r\n"):
        s = s[:-2]
    elif s.endswith(b"\n"):
        s = s[:-1]
    return s


def log(line):
    with open(LOG_PATH, "a", encoding="utf-8") as f:
        f.write(line + "\n")


def connect():
    c = sqlite3.connect(DB_PATH, isolation_level=None, check_same_thread=False)
    c.execute("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, status TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT, seq INTEGER, history TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS pending (sub TEXT, seq INTEGER, id TEXT, type TEXT, PRIMARY KEY (sub, seq))")
    return c


CONN = connect()


def handle_event(ev):
    eid, typ, sub, seq = ev["id"], ev["type"], ev["subscription"], ev["seq"]
    logs = []
    c = CONN
    c.execute("BEGIN IMMEDIATE")
    try:
        if c.execute("SELECT 1 FROM events WHERE id=?", (eid,)).fetchone():
            c.execute("COMMIT")
            return 200, {"status": "duplicate"}
        row = c.execute("SELECT state, seq, history FROM subs WHERE id=?", (sub,)).fetchone()
        if row:
            state, last, hist = row[0], row[1], json.loads(row[2])
        else:
            state, last, hist = "none", 0, []
        if seq <= last:
            c.execute("INSERT INTO events VALUES (?, 'stale')", (eid,))
            c.execute("COMMIT")
            return 200, {"status": "stale"}
        if seq > last + 1:
            c.execute("INSERT INTO events VALUES (?, 'queued')", (eid,))
            c.execute("INSERT OR IGNORE INTO pending VALUES (?,?,?,?)", (sub, seq, eid, typ))
            c.execute("COMMIT")
            return 202, {"status": "queued"}
        c.execute("INSERT INTO events VALUES (?, 'applied')", (eid,))
        count = 0
        cur_id, cur_type, cur_seq = eid, typ, seq
        while True:
            frm, to = TRANS[cur_type]
            if state in frm:
                state = to
                hist.append(to)
            else:
                logs.append("invalid transition " + cur_id)
            last = cur_seq
            count += 1
            nxt = c.execute("SELECT id, type FROM pending WHERE sub=? AND seq=?",
                            (sub, last + 1)).fetchone()
            if not nxt:
                break
            c.execute("DELETE FROM pending WHERE sub=? AND seq=?", (sub, last + 1))
            c.execute("UPDATE events SET status='applied' WHERE id=?", (nxt[0],))
            cur_id, cur_type, cur_seq = nxt[0], nxt[1], last + 1
        c.execute("INSERT OR REPLACE INTO subs VALUES (?,?,?,?)",
                  (sub, state, last, json.dumps(hist)))
        c.execute("COMMIT")
    except Exception:
        try:
            c.execute("ROLLBACK")
        except Exception:
            pass
        raise
    for l in logs:
        log(l)
    return 200, {"status": "applied", "applied": count}


def valid(ev):
    if not isinstance(ev, dict):
        return False
    for k in ("id", "type", "subscription"):
        if not isinstance(ev.get(k), str):
            return False
    if ev["type"] not in TYPES:
        return False
    s = ev.get("seq")
    if not isinstance(s, int) or isinstance(s, bool) or s < 1:
        return False
    return True


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(b)

    def body(self):
        n = int(self.headers.get("content-length") or 0)
        return self.rfile.read(n) if n > 0 else b""

    def path_only(self):
        return self.path.split("?", 1)[0]

    def do_POST(self):
        try:
            body = self.body()
        except Exception:
            body = b""
        if self.path_only() != "/webhooks":
            return self.send(404, {"error": "not found"})
        try:
            secret = load_secret()
        except Exception:
            secret = None
        sig = self.headers.get("x-signature")
        ok = False
        if secret is not None and sig is not None:
            exp = ("sha256=" + hashlib.sha256(secret + b"." + body).hexdigest()).encode()
            ok = hmac.compare_digest(exp, sig.encode("latin-1", "replace"))
        if not ok:
            log("rejected signature")
            return self.send(401, {"error": "bad signature"})
        try:
            ev = json.loads(body)
        except Exception:
            ev = None
        if not valid(ev):
            return self.send(400, {"error": "invalid event"})
        with LOCK:
            code, obj = handle_event(ev)
        self.send(code, obj)

    def do_GET(self):
        p = self.path_only()
        pre = "/subscriptions/"
        if p.startswith(pre) and len(p) > len(pre) and "/" not in p[len(pre):]:
            sid = unquote(p[len(pre):])
            with LOCK:
                row = CONN.execute("SELECT state, seq, history FROM subs WHERE id=?",
                                   (sid,)).fetchone()
            if row:
                return self.send(200, {"id": sid, "state": row[0], "seq": row[1],
                                       "history": json.loads(row[2])})
        self.send(404, {"error": "not found"})

    def other(self):
        try:
            self.body()
        except Exception:
            pass
        self.send(404, {"error": "not found"})

    do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = other


ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
